package com.vandorlabs.neoforge.gear;

import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.*;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.ClipContext;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.tick.ServerTickEvent;

/** Server-owned dig timing and nearest-hit authorization. No packet can supply loot, pose or a payload cell. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeGearHarvest {
    private static final Map<ServerPlayer,Dig> DIGS=new WeakHashMap<>();
    private static final class Dig {final NativeGearEntity root;final NativeGearPayload payload;final int cell;final ItemStack tool;long renewed;float progress;Dig(ServerPlayer actor,NativeGearPayloadTrace.Hit hit){root=hit.owner();payload=root.payload();cell=hit.cell();tool=actor.getMainHandItem().copy();renewed=actor.serverLevel().getGameTime();}}
    public static NativeGearPayloadTrace.Hit target(ServerPlayer actor){if(actor==null||!actor.isAlive()||actor.isSpectator()||actor.blockActionRestricted(actor.level(),actor.blockPosition(),actor.gameMode.getGameModeForPlayer()))return null;var world=actor.serverLevel();double reach=actor.blockInteractionRange();if(!Double.isFinite(reach)||reach<=0||reach>64)return null;var start=actor.getEyePosition();var end=start.add(actor.getViewVector(1).scale(reach));if(!NativeGearAccess.rayLoaded(world,start,end))return null;var hit=NativeGearPayloadTrace.nearest(world,start,end,NativeGearEntity::progress);if(hit==null||hit.owner().payload()==null||hit.owner().payload().materialized()||!NativeGearAccess.menu(actor,hit.owner()))return null;var mechanism=NativeGearMechanismTrace.nearest(world,start,end,NativeGearEntity::progress);if(mechanism!=null&&mechanism.distanceSq()+1e-8<hit.distanceSquared())return null;var vanilla=world.clip(new ClipContext(start,end,ClipContext.Block.OUTLINE,ClipContext.Fluid.NONE,actor));if(vanilla.getType()!=HitResult.Type.MISS&&start.distanceToSqr(vanilla.getLocation())+1e-8<hit.distanceSquared())return null;var point=BlockPos.containing(hit.point());var source=hit.owner().payload().cells().get(hit.cell());if(!NativeGearFormation.loaded(world,point)||!world.mayInteract(actor,point)||!actor.mayUseItemAt(point,hit.face(),actor.getMainHandItem())||!world.mayInteract(actor,source.pos)||!actor.mayUseItemAt(source.pos,hit.face(),actor.getMainHandItem())||source.state.getDestroySpeed(world,source.pos)<0)return null;return hit;}
    static boolean allowed(NativeGearEntity root,ServerPlayer actor,int cell){var hit=target(actor);return hit!=null&&hit.owner()==root&&hit.cell()==cell;}
    public static boolean dig(ServerPlayer actor,NativeGearHarvestPayload packet){if(!actor.getServer().isSameThread())return false;if(packet.abort()){DIGS.remove(actor);return true;}var hit=target(actor);if(hit==null||!packet.root().equals(hit.owner().getBlockPos())||!packet.identity().equals(hit.owner().identity())||NativeGearJournal.busy(hit.owner())){DIGS.remove(actor);return false;}var old=DIGS.get(actor);if(old!=null&&old.root==hit.owner()&&old.payload==hit.owner().payload()&&old.cell==hit.cell()&&ItemStack.matches(old.tool,actor.getMainHandItem()))old.renewed=actor.serverLevel().getGameTime();else{if(DIGS.size()>=256)return false;DIGS.put(actor,new Dig(actor,hit));}return true;}
    @SubscribeEvent public static void tick(ServerTickEvent.Post event){if(!NativeGearBindings.enabled())return;for(var iterator=DIGS.entrySet().iterator();iterator.hasNext();){var entry=iterator.next();var actor=entry.getKey();var dig=entry.getValue();var world=actor.serverLevel();if(actor.getServer()!=event.getServer())continue;if(world.getGameTime()-dig.renewed>10||dig.root.getLevel()!=world||dig.root.payload()!=dig.payload||!ItemStack.matches(dig.tool,actor.getMainHandItem())||!allowed(dig.root,actor,dig.cell)||NativeGearJournal.busy(dig.root)){iterator.remove();continue;}var cell=dig.payload.cells().get(dig.cell);float step=actor.isCreative()?1:cell.state.getDestroyProgress(actor,world,cell.pos);if(!Float.isFinite(step)||step<=0){iterator.remove();continue;}dig.progress+=step;if(dig.progress<1)continue;iterator.remove();if(net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.level.BlockEvent.BreakEvent(world,cell.pos,cell.state,actor)).isCanceled())continue;try{dig.root.authorize(actor);var receipt=NativeGearHarvestReceipt.prepare(dig.root,actor,dig.cell);var status=NativeGearJournal.harvest(dig.root,actor,receipt);if(status==NativeGearJournal.Status.PENDING)dig.root.journalWaiting("Preparing captured block harvest");}catch(RuntimeException refused){actor.displayClientMessage(net.minecraft.network.chat.Component.literal(Objects.toString(refused.getMessage(),"Captured block harvest refused")),true);}}}
    @SubscribeEvent public static void unload(net.neoforged.neoforge.event.level.LevelEvent.Unload event){DIGS.entrySet().removeIf(entry->entry.getKey().level()==event.getLevel()||entry.getValue().root.getLevel()==event.getLevel());}
    private NativeGearHarvest(){}
}
